internal static class Alpha7Checks
{
    public static IEnumerable<(string Name,Action Run)> All(){
        yield return("alpha7 exact 180 schema sections defaults and restart requirements",Schema);
        yield return("alpha7 generation selection persists exact keys and restores original bytes",Modes);
        yield return("alpha7 multi-section INI preserves comments unknown keys BOM and CRLF",Preservation);
        yield return("alpha7 duplicate sections keys invalid values and malformed headers fail closed",Invalid);
        yield return("alpha7 older and malformed versions do not inherit 180 settings",Versions);
        yield return("alpha7 XMX and stock 2x use integer equals one semantics",Integers);
        yield return("alpha7 XMX locks NVIDIA-only writes even on direct service calls",Lockout);
        yield return("alpha7 settings stale reload and process guard do not write",Stale);
        yield return("alpha7 existing Intel preparation catalog and 180 API gates remain exact",Intel);
        yield return("alpha7 genuine Intel pair passes existing integrity verification without execution",IntelFiles);
        yield return("alpha7 diagnostic configuration is separate from files loaded and active",Diagnostics);
        yield return("alpha7 reviewed 180 log schema preserves process session correlation",Session);
        yield return("alpha7 manual workflow explains missing stale blocked unconfirmed and unchanged plans",Reasons);
        yield return("alpha7 manual verification controls and invalidation unshown WPF",ManualUi);
        yield return("alpha7 generation selector locks NVIDIA rows and preserves their saved values unshown WPF",SettingsUi);
        yield return("alpha7 six-language added messages and dot-separated technical versions",Localization);
        yield return("alpha7 Intel 180 synthetic addon identity genuine pair Preview Apply repeat Restore",Intel180Cycle);
    }
    private static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);}
    private static void Reject(Action action){try{action();}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or IOException){return;}throw new Exception("Expected refusal");}
    private static string Temp(){var p=Path.Combine(Path.GetTempPath(),"RenoDX-alpha7",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}
    private static (string Root,string Path,MfgUnlockSettingsService Service) Fixture(string text="") {var r=Temp();var p=Path.Combine(r,"MFGAdaUnlock.ini");if(text.Length>0)File.WriteAllText(p,text,new UTF8Encoding(false));return(r,p,new(true));}
    private static Dictionary<string,string> Mode(string mode)=>new(){{"Selected",mode=="XeMFG"?"XeMFG":"DLSSG"},{"XmxGenerator",mode=="XMX"?"1":"0"}};
    private static void Schema(){var f=Fixture();var s=f.Service.Load(f.Path,f.Root,"1.8.0.0");Check(s.IsSupportedAddonVersion&&s.Settings.Count==8,"Exact 180 schema missing");Check(s.Settings.All(v=>v.IsValid&&!v.IsExplicitlySet&&v.Definition.RequiresRestart),"Missing defaults / restart metadata");foreach(var (key,section,value) in new[]{("Selected","Backend","DLSSG"),("XmxGenerator","DLSSG","0"),("ForceBorderless","DLSSG","0"),("XeFGStock2xModel","XeFG","0")}){var d=s.Settings.Single(v=>v.Definition.Key==key);Check(f.Service.SectionFor(d.Definition)==section&&d.EffectiveValue==value,"Wrong key / section / default: "+key);}Check(!File.Exists(f.Path),"Read-only load created a file");}
    private static void Modes(){var f=Fixture("; original\n[Other]\nKeep=yes\n");var original=File.ReadAllBytes(f.Path);var backup=new BackupRestoreService(Temp());foreach(var mode in new[]{"XMX","XeMFG","DLSSG"}){var s=f.Service.Load(f.Path,f.Root,"1.8.0.0");var tx=f.Service.PrepareTransaction(s,Mode(mode),()=>true);Check(File.ReadAllBytes(f.Path).SequenceEqual(original),"Preparation wrote config");var result=backup.ExecuteAsync(f.Root,[tx]).GetAwaiter().GetResult();var loaded=f.Service.Load(f.Path,f.Root,"1.8.0.0");Check(MfgUnlockSettingsService.XmxSelected(loaded.Settings)==(mode=="XMX"),"Wrong selected mode");Check(RuntimeDiagnosticsService.ConfigurationEvidence(loaded).Contains(mode=="XMX"?"XMX (experimental)":mode=="XeMFG"?"Intel XeMFG (CUDA)":"NVIDIA DLSS-G"),"Mode not reflected");backup.RestoreAsync(f.Root,result.TransactionId).GetAwaiter().GetResult();Check(File.ReadAllBytes(f.Path).SequenceEqual(original),"Restore lost exact original");}}
    private static void Preservation(){var f=Fixture();var original="; header\r\n[Backend]\r\nSelected=DLSSG\r\nOther=7 ; keep\r\n[DLSSG]\r\nXmxGenerator=0 ; preserve\r\nForeign=a\r\n[XeFG]\r\nXeFGStock2xModel=0\r\n[Other]\r\nSelected=foreign\r\n";File.WriteAllText(f.Path,original,new UTF8Encoding(true));var bytes=f.Service.CreateUpdatedBytes(f.Service.Load(f.Path,f.Root,"1.8.0.0"),new Dictionary<string,string>{{"Selected","XeMFG"},{"XmxGenerator","1"},{"XeFGStock2xModel","1"}});Check(bytes.Take(3).SequenceEqual(new byte[]{239,187,191}),"BOM lost");var output=Encoding.UTF8.GetString(bytes.AsSpan(3));Check(output==original.Replace("Selected=DLSSG","Selected=XeMFG").Replace("XmxGenerator=0","XmxGenerator=1").Replace("XeFGStock2xModel=0","XeFGStock2xModel=1"),"Untouched INI changed");Check(File.ReadAllText(f.Path)==original,"Byte preparation wrote disk");}
    private static void Invalid(){foreach(var input in new[]{"[Backend]\nSelected=DLSSG\nSelected=XeMFG\n","[DLSSG]\nXmxGenerator=1\n[dlssg]\nXmxGenerator=0\n","[ Backend ]\nSelected=DLSSG\n"}){var f=Fixture(input);Reject(()=>f.Service.Load(f.Path,f.Root,"1.8.0.0"));}foreach(var input in new[]{"[Backend]\nSelected=Fake\n","[DLSSG]\nXmxGenerator=bad\n","[XeFG]\nXeFGStock2xModel=true\n"}){var f=Fixture(input);var s=f.Service.Load(f.Path,f.Root,"1.8.0.0");Check(s.Settings.Any(x=>!x.IsValid),"Bad value silently accepted");Reject(()=>f.Service.CreateUpdatedBytes(s,Mode("XMX")));Check(File.ReadAllText(f.Path)==input,"Bad config overwritten");}}
    private static void Versions(){var f=Fixture();foreach(var v in new[]{"1.6.0.0","1.7.0.0","1.8.0-beta.1","Unknown"}){var s=f.Service.Load(f.Path,f.Root,v);Check(!s.Settings.Any(x=>x.Definition.Key=="XmxGenerator"),"180 settings leaked to "+v);Reject(()=>f.Service.CreateUpdatedBytes(s,Mode("XMX")));}var main=new MfgUnlockSettingsService();Check(main.DefinitionsFor("1.6.0.0").Count==6&&main.DefinitionsFor("1.7.0.0").Count==7&&main.DefinitionsFor("1.8.0.0").Count==7,"Earlier ReShade schema changed");Check(main.SupportsVersion("1.8.0.0")&&!main.SupportsVersion("1.8.0-beta.1"),"Future version inherited write grant");}
    private static void Integers(){foreach(var n in new[]{"1","2","-1","0"}){var f=Fixture("[Backend]\nSelected= dlssg \n[DLSSG]\nXmxGenerator="+n+"\n[XeFG]\nXeFGStock2xModel="+n+"\n");var s=f.Service.Load(f.Path,f.Root,"1.8.0.0");Check(MfgUnlockSettingsService.XmxSelected(s.Settings)==(n=="1"),"XMX integer !=1 enabled");Check(s.Settings.Single(x=>x.Definition.Key=="XeFGStock2xModel").EffectiveValue==(n=="1"?"1":"0"),"Stock integer semantics wrong");}}
    private static void Lockout(){var f=Fixture("[Backend]\nSelected=DLSSG\n[DLSSG]\nXmxGenerator=1\n");var main=new MfgUnlockSettingsService();var path=Path.Combine(f.Root,"ReShade.ini");File.WriteAllText(path,"[RenoDX.MFGUnlock]\nTemporalFix=1\nDynamicMFG=1 ; preserve\n");var s=main.Load(path,f.Root,"1.8.0.0");foreach(var key in new[]{"TemporalFix","BlackwellFrameworkKernels","ExperimentalAdaptiveQuality","Rtx50QualityFixes"})Reject(()=>main.CreateUpdatedBytes(s,new Dictionary<string,string>{{key,"0"}}));var bytes=main.CreateUpdatedBytes(s,new Dictionary<string,string>{{"Enabled","0"}});Check(Encoding.UTF8.GetString(bytes).Contains("DynamicMFG=1 ; preserve"),"NVIDIA saved preference erased");File.WriteAllBytes(f.Path,f.Service.CreateUpdatedBytes(f.Service.Load(f.Path,f.Root,"1.8.0.0"),Mode("DLSSG")));Check(main.CreateUpdatedBytes(s,new Dictionary<string,string>{{"TemporalFix","0"}}).Length>0,"Switch-back did not unlock after reload");}
    private static void Stale(){var f=Fixture("[Backend]\nSelected=DLSSG\n");var s=f.Service.Load(f.Path,f.Root,"1.8.0.0");Reject(()=>f.Service.PrepareTransaction(s,Mode("XMX"),()=>false));File.AppendAllText(f.Path,"; changed\n");Reject(()=>f.Service.CreateUpdatedBytes(s,Mode("XMX")));var reloaded=f.Service.Load(f.Path,f.Root,"1.8.0.0");Check(Encoding.UTF8.GetString(f.Service.CreateUpdatedBytes(reloaded,Mode("XMX"))).Contains("; changed"),"Reload lost latest bytes");Check(!File.ReadAllText(f.Path).Contains("XmxGenerator"),"Blocked preparation wrote disk");}
    private static void Intel(){Check(IntelRuntimeService.SupportsIntegration("1.8.0.0",IntelIntegration.D3D12)&&IntelRuntimeService.SupportsIntegration("1.8.0.0",IntelIntegration.VulkanExperimental),"Reviewed 180 version unavailable");Check(!IntelRuntimeService.SupportsAddon("1.8.0-beta.1")&&!IntelRuntimeService.SupportsIntegration("1.8.0.0",(IntelIntegration)9),"Unknown integration granted");var pair=IntelRuntimeService.Assets.Where(a=>a.Version.Length>0).ToArray();Check(pair.Length==2&&pair[0].Version=="1.3.1.78"&&pair[1].Version=="1.3.2.10"&&pair[0].Sha256=="ec5e0c65e075570c6ede72618bb666d0be0c2e10b2ea9762c0fe8cb8e375ab27"&&pair[1].Sha256=="d2030dcd694fda8f2ec7e044b13e6db8f0b56d4ba9113a5efad334e3f3ded8c7","Pinned dependency changed");}
    private static void IntelFiles(){var cache=Environment.GetEnvironmentVariable("RENODX_TEST_INTEL_CACHE");if(cache is null)throw new SkipCheckException("Genuine cached Intel fixture unavailable");var root=Temp();var service=new IntelRuntimeService(root);foreach(var asset in IntelRuntimeService.Assets.Where(a=>a.Version.Length>0)){var source=Directory.GetFiles(cache,asset.Name,SearchOption.AllDirectories).Single();var target=Path.Combine(root,asset.Name);File.Copy(source,target);service.VerifyFileAsync(target,asset).GetAwaiter().GetResult();File.AppendAllText(target,"changed");Reject(()=>service.VerifyFileAsync(target,asset).GetAwaiter().GetResult());}Check(!Directory.GetFiles(root).Any(p=>p.EndsWith(".exe")),"Unwanted executable created");}
    private static void Intel180Cycle(){
        var fixture=Environment.GetEnvironmentVariable("RENODX_TEST_INTEL_CACHE")??throw new SkipCheckException("Genuine cached Intel fixture unavailable");
        var cache=Temp();var packagePath=Path.Combine(cache,IntelRuntimeService.Commit);Directory.CreateDirectory(packagePath);
        foreach(var asset in IntelRuntimeService.Assets)File.Copy(Path.Combine(fixture,asset.Name),Path.Combine(packagePath,asset.Name));
        var root=Temp();var exe=Path.Combine(root,"Own-alpha7.exe");File.Copy(Environment.ProcessPath!,exe);var addon=Path.Combine(root,"renodx-mfgunlock.addon64");File.WriteAllText(addon,"synthetic identity only; never loaded");var original=Directory.GetFiles(root).ToDictionary(p=>Path.GetFileName(p)!,p=>File.ReadAllBytes(p));
        var addonVersion="1.8.0.0";var service=new IntelRuntimeService(cache,null,p=>Path.GetExtension(p)==".addon64"?addonVersion:"",_=>false);var package=new VerifiedIntelRuntime(packagePath);var backup=new BackupRestoreService(Temp());
        foreach(var api in new[]{IntelIntegration.D3D12,IntelIntegration.VulkanExperimental}){
            var preview=service.PreviewAsync(package,root,exe,root,true,api).GetAwaiter().GetResult();Check(Directory.GetFiles(root).Length==original.Count,"Preview wrote files");
            addonVersion="1.8.0-beta.1";Reject(()=>service.InstallAsync(package,preview,true,backup).GetAwaiter().GetResult());addonVersion="1.8.0.0";
            var result=service.InstallAsync(package,preview,true,backup).GetAwaiter().GetResult()!;foreach(var a in IntelRuntimeService.Assets)service.VerifyFileAsync(Path.Combine(root,a.Name),a).GetAwaiter().GetResult();
            var repeat=service.PreviewAsync(package,root,exe,root,true,api).GetAwaiter().GetResult();Check(service.InstallAsync(package,repeat,true,backup).GetAwaiter().GetResult() is null,"Identical reinstall wrote again");backup.RestoreAsync(root,result.TransactionId).GetAwaiter().GetResult();Check(Directory.GetFiles(root).Length==original.Count&&original.All(p=>File.ReadAllBytes(Path.Combine(root,p.Key!)).SequenceEqual(p.Value)),"Original synthetic folder not restored");
        }
    }
    private static void Diagnostics(){var f=Fixture("[Backend]\nSelected=DLSSG\n[DLSSG]\nXmxGenerator=1\n");var s=f.Service.Load(f.Path,f.Root,"1.8.0.0");var text=RuntimeDiagnosticsService.ConfigurationEvidence(s);Check(text.Contains("XMX")&&text.Contains("not verified"),"Config claimed activity");var exe=Path.Combine(f.Root,"Own.exe");var log=new RuntimeLogInput(Path.Combine(f.Root,"ReShade.log"),"Initializing crosire's ReShade version '6.8.0' into '"+exe+"' (0x1)\nmfgunlock: xmx slot 0 hooked root\nmfgunlock: xmx execute result 0\nmfgunlock: xmx failed: test failure",DateTimeOffset.UtcNow);var r=RuntimeDiagnosticsService.Analyze(exe,"1.0.0.0",new(null,null,"not running"),[log],DateTimeOffset.UtcNow);Check(r.Evidence.Count(e=>e.StartsWith("Recorded XMX evidence"))==3&&r.Statuses.Any(x=>x.StartsWith("XMX: Not verified"))&&!r.Statuses.Any(x=>x.Contains(": Active reported")),"Hook/execute promoted to current-active");}
    private static void Session(){var now=DateTimeOffset.Parse("2026-11-01T12:00:00Z");var exe=Path.Combine(Temp(),"Own.exe");var text="{\"event\":\"native_session\",\"utc\":\"2026-11-01T11:59:00Z\",\"executable\":\"Own.exe\",\"executable_version\":\"1.0.0.0\",\"addon\":\"1.8.0\",\"pid\":42,\"tick\":1000}\n{\"event\":\"native_modules\",\"pid\":42,\"tick\":1001,\"modules\":[{\"name\":\"libxess_fg.dll\",\"version\":\"1.3.1.78\"}]}";var log=new RuntimeLogInput(Path.Combine(Path.GetDirectoryName(exe)!,"MFGAdaUnlock-XeMFG.log"),text,now);foreach(var pid in new int?[]{42,null}){var r=RuntimeDiagnosticsService.Analyze(exe,"1.0.0.0",new(pid,now.AddMinutes(-1),"synthetic identity"),[log],now);Check(r.Evidence.Any(e=>e.StartsWith(pid==42?"Current process session matched":"Previous / unverified session")),"180 session correlation broken");Check(!r.Statuses.Any(x=>x.Contains(": Active reported")),"Module version alone granted activity");}}
    private static NvidiaManualPlan Plan()=>new("root","exe","target","fingerprint",["a.dll"],[new("a.dll","source","target","2","hash","1","old","Replace existing",true,true,"snapshot")],[],false,false);
    private static void Reasons(){var p=Plan();Check(NvidiaManualWorkflow.DisabledReason(null,true,false)==NvidiaManualWorkflow.Changed,"No-plan instructions missing");Check(NvidiaManualWorkflow.DisabledReason(p,false,false).Contains("outdated"),"Stale reason");Check(NvidiaManualWorkflow.DisabledReason(p,true,false).Contains("acknowledgement"),"Consent reason");Check(NvidiaManualWorkflow.DisabledReason(p with{Entries=[p.Entries[0] with{Action="Blocked"}]},true,false).Contains("blocked"),"Blocked reason");Check(NvidiaManualWorkflow.DisabledReason(p with{Entries=[p.Entries[0] with{IsSelected=false,Action="No change"}]},true,false).Contains("No applicable"),"No-change reason");Check(NvidiaManualWorkflow.DisabledReason(p,true,true).Contains("progress"),"Busy reason");}
    private const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
    private static void Set(MainWindow w,string name,object? value)=>typeof(MainWindow).GetField(name,Flags)!.SetValue(w,value);
    private static object? Get(MainWindow w,string name)=>typeof(MainWindow).GetField(name,Flags)!.GetValue(w);
    private static void Call(MainWindow w,string name)=>typeof(MainWindow).GetMethod(name,Flags)!.Invoke(w,null);
    private static void ManualUi()=>WpfCheckHost.Run(()=>{LocalizedPresentation.Language.SetCulture("en-US",false);var w=new MainWindow();try{Call(w,"OpenManualNvidia");var v=(NvidiaManualDllView)Get(w,"manualDllView")!;Check((string)v.PreviewButton.Content=="Verify Selected DLLs"&&(string)v.ApplyButton.Content=="Apply Verified Changes","Labels not updated");Check(v.ApplyReasonText.Text==NvidiaManualWorkflow.Changed&&!v.ApplyButton.IsEnabled,"Unverified Apply enabled");Set(w,"manualDllPlan",Plan() with{Acknowledged=true,CanApply=true});Call(w,"InvalidateManualNvidia");Check(Get(w,"manualDllPlan") is null&&v.Consent.IsChecked!=true&&!v.ApplyButton.IsEnabled,"Invalidation retained approval");Call(w,"RenderManualNvidia");Check(v.WorkflowText.Text==NvidiaManualWorkflow.Steps,"Steps missing");foreach(var culture in UiLocalization.Cultures){LocalizedPresentation.Language.SetCulture(culture,false);Call(w,"RenderManualNvidia");Check(v.ApplyReasonText.Text==LocalizedPresentation.Language.Lookup(NvidiaManualWorkflow.Changed),"Late reason untranslated");}}finally{w.Close();LocalizedPresentation.Language.SetCulture("en-US",false);}});
    private static void SettingsUi()=>WpfCheckHost.Run(()=>{var w=new MainWindow();try{var rowType=typeof(MainWindow).GetNestedType("MfgUnlockSettingRow",BindingFlags.NonPublic)!;object Row(MfgUnlockSettingDefinition d,string value)=>Activator.CreateInstance(rowType,[d,"saved",value,true,(Action)(()=>{})])!;var xe=(System.Collections.IList)Get(w,"xeMfgSettingRows")!;var main=(System.Collections.IList)Get(w,"mfgSettingRows")!;var defs=new MfgUnlockSettingsService(true).DefinitionsFor("1.8.0.0");var backend=Row(defs.Single(d=>d.Key=="Selected"),"DLSSG");var xmx=Row(defs.Single(d=>d.Key=="XmxGenerator"),"1");xe.Add(backend);xe.Add(xmx);var temporal=Row(new MfgUnlockSettingsService().DefinitionsFor("1.8.0.0").Single(d=>d.Key=="TemporalFix"),"1");main.Add(temporal);Call(w,"UpdateGenerationMode");Check(!(bool)rowType.GetProperty("CanEdit")!.GetValue(temporal)!,"XMX did not lock NVIDIA field");Check((string)rowType.GetProperty("ProposedValue")!.GetValue(temporal)! == "1","Locked value erased");rowType.GetProperty("ProposedValue")!.SetValue(xmx,"0");Call(w,"UpdateGenerationMode");Check((bool)rowType.GetProperty("CanEdit")!.GetValue(temporal)!,"DLSS-G switch did not restore editability");Check(((StackPanel)w.FindName("GenerationModePanel")).Children.Count==3,"Method selector not built");}finally{w.Close();}});
    private static void Localization(){var l=new UiLocalization();Check(l.ValidateCatalogs().Count==0,"Catalog integrity");foreach(var c in UiLocalization.Cultures){l.SetCulture(c,false);foreach(var key in new[]{"Verify Selected DLLs","Apply Verified Changes",NvidiaManualWorkflow.Changed,NvidiaManualWorkflow.Steps,"XeMFG via DLSS-G (XMX, experimental)","Generation backend","Intel stock 2x model"})Check(l.GetCatalog(c).ContainsKey(key)&&(c=="en-US"||l.Lookup(key)!=key||c=="pt-BR"&&key=="XeMFG via DLSS-G (XMX, experimental)"),"Missing translation "+c+" "+key);Check(TechnicalVersionDisplay.Format("1,3,1,78")=="1.3.1.78"&&TechnicalVersionDisplay.Format("1,8,0")=="1.8.0","Localized technical version");Check(l.Translate("Generation configuration: XMX (experimental) · saved preference only; loaded runtime and generation activity are not verified.").Contains(c=="en-US"?"experimental":l.Lookup("XMX (experimental)").Split('(')[1].TrimEnd(')')),"Nested mode label untranslated");}}
}

